import { ensureInteractivityPluginLoaded } from "@tsparticles/plugin-interactivity";
import { Popper } from "./Popper.js";
export async function loadExternalPopInteraction(engine) {
    engine.checkVersion("4.3.2");
    await engine.pluginManager.register((e) => {
        ensureInteractivityPluginLoaded(e);
        e.pluginManager.addInteractor?.("externalPop", container => {
            return Promise.resolve(new Popper(container));
        });
    });
}
